const storageWarnings=new Set();
function isLocalFileMode(){return location.protocol==='file:'}
function connectionAllowsEditing(){return isLocalFileMode()||navigator.onLine}
let storageWritesBlocked=false;
let storageBooting=true;
class StoragePersistenceError extends Error{constructor(){super('Yerel veriler kaydedilemedi.');this.name='StoragePersistenceError'}}
function showStorageWarning(){
  const banner=document.querySelector('#storageWarning');
  if(!banner)return;
  banner.hidden=false;
  banner.querySelector('span').textContent=[...storageWarnings].join(' ');
}
function blockStorage(message){storageWritesBlocked=true;storageWarnings.add(message);showStorageWarning()}
function getStoredItem(key){
  try{return localStorage.getItem(key)}
  catch{blockStorage('Tarayıcının yerel verilerine erişilemiyor. Ekrandaki kayıtlar eksik veya örnek olabilir; bu oturumdaki değişiklikler kaydedilemez. Tarayıcı verilerini silmeyin.');return null}
}
function readStoredJson(key,fallback,isValid){
  const raw=getStoredItem(key);
  if(raw===null)return fallback;
  try{
    const value=JSON.parse(raw);
    if(value===null)return fallback;
    if(isValid(value))return value;
  }catch{}
  blockStorage(`"${key}" kaydı okunamadı. Ham veri korunuyor; ekrandaki kayıtlar eksik veya örnek olabilir. Düzeltme yapılana kadar değişiklikler kaydedilemez.`);
  return fallback;
}
function setStoredItem(key,value,background=false){
  if(storageWritesBlocked){if(background||storageBooting)return false;throw new StoragePersistenceError()}
  try{localStorage.setItem(key,value);return true}
  catch{
    blockStorage('Tarayıcı depolaması dolu veya erişime kapalı. Son değişiklik kaydedilmedi; yer açıp sayfayı yenileyin. Mevcut kayıtlar silinmedi.');
    if(background||storageBooting)return false;
    throw new StoragePersistenceError();
  }
}
function localDataBackup(){
  const records={};
  for(let index=0;index<localStorage.length;index++){
    const key=localStorage.key(index);
    if(key?.startsWith('cps-'))records[key]=localStorage.getItem(key);
  }
  return{exportedAt:new Date().toISOString(),format:'cps-raw-local-storage-v1',records};
}
document.querySelector('#exportLocalData')?.addEventListener('click',()=>{
  try{
    const backup=localDataBackup(),blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');
    link.href=url;link.download=`cps-yerel-yedek-${localDateKey()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  }catch{storageWarnings.add('Yerel verilere erişilemediği için yedek oluşturulamadı. Tarayıcı verilerini silmeyin.');showStorageWarning()}
});
function getSessionItem(key){try{return sessionStorage.getItem(key)}catch{return null}}
function setSessionItem(key,value){try{sessionStorage.setItem(key,value);return true}catch{return false}}
