function translateUiText(value){if(language==='tr'||!value)return value;const leading=value.match(/^\s*/)?.[0]||'',trailing=value.match(/\s*$/)?.[0]||'',core=value.trim();if(englishUi[core])return `${leading}${englishUi[core]}${trailing}`;let translated=core;Object.entries(englishUi).sort((a,b)=>b[0].length-a[0].length).forEach(([tr,en])=>{translated=translated.split(tr).join(en)});translated=translated.replace(/\bAğu\b/g,'Aug').replace(/\bEyl\b/g,'Sep').replace(/\bEki\b/g,'Oct').replace(/\bŞub\b/g,'Feb').replace(/\bNis\b/g,'Apr').replace(/\bHaz\b/g,'Jun').replace(/\bTem\b/g,'Jul').replace(/\bAra\b/g,'Dec');return `${leading}${translated}${trailing}`}
