function translateInterface(root=document){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:node=>node.parentElement?.closest('script,style')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});let node;while(node=walker.nextNode()){if(!translationSources.has(node))translationSources.set(node,node.nodeValue);node.nodeValue=language==='tr'?translationSources.get(node):translateUiText(translationSources.get(node))}root.querySelectorAll?.('[placeholder],[aria-label],[title]').forEach(element=>{let sources=translationSources.get(element);if(!sources||typeof sources==='string'){sources={};translationSources.set(element,sources)};['placeholder','aria-label','title'].forEach(attribute=>{if(!element.hasAttribute(attribute))return;if(!(attribute in sources))sources[attribute]=element.getAttribute(attribute);element.setAttribute(attribute,language==='tr'?sources[attribute]:translateUiText(sources[attribute]))})});root.querySelectorAll?.('[data-i18n-value]').forEach(element=>{let sources=translationSources.get(element);if(!sources||typeof sources==='string'){sources={};translationSources.set(element,sources)};if(language==='tr'){if(sources.value!==undefined)element.value=sources.value}else{if(sources.value===undefined||element.value!==translateUiText(sources.value))sources.value=element.value;element.value=translateUiText(sources.value)}});root.querySelectorAll?.('option:not([value])').forEach(option=>option.setAttribute('value',(translationSources.get(option.firstChild)||option.textContent).trim()))}

function hasRole(...roles){return Boolean(currentUser&&(currentUser.role==='admin'||roles.includes(currentUser.role)))}
function populateUserSelectors(){const salesUsers=userDirectory.filter(user=>['admin','sales'].includes(user.role)),technicians=userDirectory.filter(user=>user.role==='technician');$$('select[name="salesEngineer"]').forEach(select=>{const selected=select.value;select.innerHTML=salesUsers.map(user=>`<option>${escapeHtml(user.name)}</option>`).join('');if([...select.options].some(option=>option.value===selected))select.value=selected});$$('select[name="technician"]').forEach(select=>{const selected=select.value;select.innerHTML=`<option value="">Teknisyen seçin</option>${technicians.map(user=>`<option>${escapeHtml(user.name)}</option>`).join('')}`;if([...select.options].some(option=>option.value===selected))select.value=selected})}
function renderUsers(){const rows=$('#userRows');if(!rows)return;rows.innerHTML=userDirectory.map(user=>`<tr><td><div class="technician"><span class="mini-avatar">${escapeHtml(user.initials)}</span><strong>${escapeHtml(user.name)}</strong></div></td><td>${escapeHtml(user.title)}</td><td><span class="status planned">${escapeHtml(user.roleLabel)}</span></td><td><code>${escapeHtml(user.username)}</code></td><td><span class="user-active"><i></i>Aktif</span></td></tr>`).join('')}
function renderQuickLogins(){const container=$('#quickLoginAccounts');if(!container)return;const roleOrder=['admin','supervisor','sales','technician'],roleNames={admin:'Yönetici',supervisor:'Servis Süpervisörü',sales:'Satış Mühendisi',technician:'Servis Teknisyeni'},users=roleOrder.map(role=>userDirectory.find(user=>user.role===role)).filter(Boolean);container.innerHTML=`<p>Demo hızlı giriş</p>${users.map(user=>`<button type="button" data-quick-login="${escapeHtml(user.username)}"><span class="demo-avatar">${escapeHtml(user.initials)}</span><span><b>${escapeHtml(roleNames[user.role])}</b><small>${escapeHtml(user.name)}</small></span></button>`).join('')}<small>Bir kullanıcı tipini seçerek doğrudan giriş yapabilirsiniz.</small>`}
// Keep the lightweight login screen independent from the heavier application render chain.
renderQuickLogins();
const columnFilterLabels={customer:'Müşteri',salesOrderNumber:'SO No',requestDate:'Talep tarihi',salesEngineer:'Satış mühendisi',status:'Durum',plannedDate:'Planlanan kurulum',technician:'Teknisyen',progress:'İlerleme'};
function progressRange(value){const progress=Number(value||0);if(progress<25)return '%0–24';if(progress<50)return '%25–49';if(progress<75)return '%50–74';if(progress<100)return '%75–99';return '%100'}
function parseRecordDate(iso,display){if(iso&&/^\d{4}-\d{2}-\d{2}$/.test(iso))return new Date(`${iso}T12:00:00`);const match=String(display||'').match(/(\d{1,2})\s+([A-Za-zÇĞİÖŞÜçğıöşü]+)\s+(\d{4})/),months={oca:0,şub:1,mar:2,nis:3,may:4,haz:5,tem:6,ağu:7,eyl:8,eki:9,kas:10,ara:11};return match&&months[match[2].toLocaleLowerCase('tr-TR')]!==undefined?new Date(Number(match[3]),months[match[2].toLocaleLowerCase('tr-TR')],Number(match[1])):null}
function dateForColumn(item,key){if(key==='requestDate'&&currentUser?.role==='technician')return parseRecordDate(item.planningAssignedAt||item.planningUpdatedAt);return key==='requestDate'?parseRecordDate(item.requestDateIso,item.requestDate):parseRecordDate(item.plannedDateIso,item.date)}
function monthKey(item,key){const date=dateForColumn(item,key);return date?`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`:'Tarih yok'}
function columnValue(item,key){return {customer:item.customer,salesOrderNumber:item.salesOrderNumber,requestDate:monthKey(item,'requestDate'),salesEngineer:item.salesEngineer,status:item.status,plannedDate:monthKey(item,'plannedDate'),technician:calendarAssignees(item).join(', ')||item.tech,progress:progressRange(item.progress)}[key]||'—'}
function columnFilterValues(key){return [...new Set(installations.map(item=>columnValue(item,key)).filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b),'tr',{numeric:true}))}
function renderColumnFilterOptions(query=''){const normalized=normalizeSearch(query),values=columnFilterValues(activeColumnFilter);if(['requestDate','plannedDate'].includes(activeColumnFilter)){const monthNames=['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık'],dated=values.filter(value=>/^\d{4}-\d{2}$/.test(value)&&normalizeSearch(`${value.slice(0,4)} ${monthNames[Number(value.slice(5))-1]}`).includes(normalized)),years=[...new Set(dated.map(value=>value.slice(0,4)))].sort((a,b)=>b-a);$('#columnFilterOptions').innerHTML=years.length?years.map(year=>{const months=dated.filter(value=>value.startsWith(`${year}-`)),allSelected=months.every(value=>pendingColumnSelection.has(value));return `<section class="date-filter-year"><label class="year-filter-option"><input type="checkbox" data-filter-year="${year}" ${allSelected?'checked':''}><strong>${year}</strong></label><div>${months.map(value=>`<label class="month-filter-option"><input type="checkbox" value="${value}" ${pendingColumnSelection.has(value)?'checked':''}><span>${monthNames[Number(value.slice(5))-1]}</span></label>`).join('')}</div></section>`}).join(''):'<p>Sonuç bulunamadı.</p>';return}const filtered=values.filter(value=>normalizeSearch(value).includes(normalized));$('#columnFilterOptions').innerHTML=filtered.length?filtered.map(value=>`<label><input type="checkbox" value="${escapeHtml(value)}" ${pendingColumnSelection.has(String(value))?'checked':''}><span>${escapeHtml(value)}</span></label>`).join(''):'<p>Sonuç bulunamadı.</p>'}
function openColumnFilter(key,button){activeColumnFilter=key;pendingColumnSelection=new Set(columnFilters[key]);$('#columnFilterTitle').textContent=`${columnFilterLabels[key]} filtresi`;$('#columnFilterSearch').value='';renderColumnFilterOptions();const popover=$('#columnFilterPopover'),rect=button.getBoundingClientRect(),width=300,left=Math.max(10,Math.min(rect.left-250,window.innerWidth-width-10)),top=Math.max(10,Math.min(rect.bottom+8,window.innerHeight-430));popover.style.left=`${left}px`;popover.style.top=`${top}px`;popover.classList.remove('role-hidden');setTimeout(()=>$('#columnFilterSearch').focus(),0)}
