function statusClass(status){return {'Taslak':'draft','Devam ediyor':'progress','Planlandı':'planned','Tamamlandı':'completed','İnceleme bekliyor':'review','Satış düzeltmesi bekliyor':'returned','Planlama bekliyor':'waiting','Sevkiyat bekliyor':'waiting','Süre aşıldı':'overrun'}[status] || 'planned'}
