function salesChangeStatusMarkup(item){if(item.workflowStage==='completed')return'';const last=item.salesChangeRequestHistory?.at(-1);return last?.status==='rejected'?`<small class="sales-change-rejected" title="${escapeHtml(last.reviewNote||'')}">DEĞİŞİKLİK TALEBİ REDDEDİLDİ · ${escapeHtml(last.reviewNote||'Açıklama yok')}</small>`:''}
function rowTemplate(item){return `<tr><td><strong>${escapeHtml(item.customer)}</strong><small>${escapeHtml(item.salesOrderNumber)} · ${escapeHtml(item.ptd)}</small></td><td><span class="status ${statusClass(item.status)}">${item.status}</span></td><td><strong>${item.date}</strong><small>09:00</small></td><td><div class="technician"><span class="mini-avatar">${item.initials}</span>${escapeHtml(item.tech)}</div></td><td><span class="progress-bar"><i style="width:${item.progress}%"></i></span><small>%${item.progress}</small></td><td><button class="row-action" aria-label="Detay">›</button></td></tr>`}
function goodwillCanReview(item){if(item.recordType!=='goodwill'&&item.workOrderType!=='goodwill')return false;if(item.goodwillStage==='awaitingSalesReview')return currentUser?.role==='sales'&&ownsSalesRecord(item);if(item.goodwillStage==='awaitingManagerApproval')return currentUser?.role==='admin';if(item.goodwillStage==='awaitingSupervisorReview')return currentUser?.role==='supervisor'||currentUser?.role==='admin';return false}
function goodwillWorkOrders(parentId){return workOrders.filter(order=>Number(order.parentInstallationId)===Number(parentId)&&order.workOrderType==='goodwill')}
