function uniqueOrderProducts(products){const seen=new Set();return products.filter(product=>{const key=String(product.partNo||'').trim();if(!key||seen.has(key))return false;seen.add(key);return true})}
function shipmentProductMarkup(products,selected=[]){const selectedSet=new Set(selected);const valid=uniqueOrderProducts(products);return '<p>Bu sevkiyatta gönderilen ürünler</p>'+(valid.length?valid.map(product=>`<label><input name="shippedProducts" type="checkbox" value="${escapeHtml(product.partNo)}" ${selectedSet.has(product.partNo)?'checked':''}> <span><b>${escapeHtml(product.partNo)}</b> · ${escapeHtml(product.description)} <small>(${escapeHtml(product.qty)} adet)</small></span></label>`).join(''):'<div class="shipment-products-empty">Önce sipariş içeriğine ürün ekleyin.</div>')}
function shipmentHistory(item){const shipment=item.shipment||{};if(Array.isArray(shipment.history))return shipment.history;if(!shipment.productsShipped||!shipment.shipmentDate)return[];const selected=new Set(shipment.partialShipment?shipment.shippedProducts||[]:(item.orderProducts||[]).map(product=>product.partNo));return[{id:`legacy-shipment-${item.id}`,shipmentDate:shipment.shipmentDate,createdAt:shipment.shipmentDate,createdBy:'Eski kayıt',note:shipment.demoProductNote||'',items:uniqueOrderProducts(item.orderProducts||[]).filter(product=>selected.has(product.partNo)).map(product=>({partNo:product.partNo,description:product.description,quantity:Number(product.qty)||0}))}]}
function shipmentSummary(item){const products=uniqueOrderProducts(item.orderProducts||[]),history=shipmentHistory(item),shipped=new Map();history.forEach(entry=>(entry.items||[]).forEach(row=>shipped.set(row.partNo,(shipped.get(row.partNo)||0)+(Number(row.quantity)||0))));const rows=products.map(product=>{const ordered=Number(product.qty)||0,sent=Math.max(0,Math.min(ordered,shipped.get(product.partNo)||0));return{partNo:product.partNo,description:product.description,ordered,sent,remaining:Math.max(0,ordered-sent)}}),ordered=rows.reduce((sum,row)=>sum+row.ordered,0),sent=rows.reduce((sum,row)=>sum+row.sent,0),complete=Boolean(rows.length&&rows.every(row=>row.remaining<=0)),partial=Boolean(sent>0&&!complete);return{history,rows,ordered,sent,remaining:Math.max(0,ordered-sent),complete,partial,status:complete?'completed':partial?'partial':'waiting',label:complete?'Sevkiyat tamamlandı':partial?'Parçalı sevkiyat':'Sevkiyat'}}
const shipmentSummaryBase=shipmentSummary;shipmentSummary=item=>item?.workOrderType==='goodwill'?{history:[],rows:[],ordered:0,sent:0,remaining:0,complete:true,partial:false,status:'completed',label:'Goodwill iş emrinde sevkiyat kontrolü gerekmez'}:shipmentSummaryBase(item);
function shipmentBadgeMarkup(item,editable=false){const summary=shipmentSummary(item),detail=summary.complete?(summary.history.at(-1)?.shipmentDate||''):summary.partial?`${summary.sent}/${summary.ordered} adet`:'';return `<button class="row-action planning-action shipment-action shipment-${summary.status}" data-${editable?'shipment-installation':'shipment-view'}-id="${item.id}">${summary.label}${detail?` <small>${escapeHtml(detail)}</small>`:''}</button>`}
function shipmentProductSet(item,partNo){return(item.orderProducts||[]).find(product=>product.partNo===partNo)?.setInfo?.trim()||'Set atanmamış'}
function shipmentState(row){return row.remaining<=0?{key:'complete',icon:'✓',label:'Tamamı sevk edildi'}:row.sent>0?{key:'partial',icon:'◐',label:'Kısmi sevk'}:{key:'waiting',icon:'×',label:'Sevk edilmedi'}}
function shipmentStatusProductMarkup(item){const summary=shipmentSummary(item);return summary.rows.length?`<div class="shipment-status-table"><div class="shipment-status-head"><span>ÜRÜN</span><span>SET</span><span>SİPARİŞ</span><span>SEVK</span><span>KALAN</span><span>DURUM</span></div>${summary.rows.map(row=>{const state=shipmentState(row);return `<div class="shipment-status-row"><span><b>${escapeHtml(row.partNo)}</b><small>${escapeHtml(row.description||'')}</small></span><span>${escapeHtml(shipmentProductSet(item,row.partNo))}</span><strong>${Math.floor(row.ordered)}</strong><strong>${Math.floor(row.sent)}</strong><strong>${Math.floor(row.remaining)}</strong><em class="shipment-state-badge ${state.key}"><i>${state.icon}</i>${state.label}</em></div>`}).join('')}</div>`:'<div class="shipment-history-empty">Sipariş ürün bilgisi bulunmuyor.</div>'}
function shipmentStatusSetMarkup(item){const rows=shipmentSummary(item).rows,groups=new Map();rows.forEach(row=>{const name=shipmentProductSet(item,row.partNo),values=groups.get(name)||[];values.push(row);groups.set(name,values)});return groups.size?[...groups.entries()].map(([name,products])=>{const total={ordered:products.reduce((sum,row)=>sum+row.ordered,0),sent:products.reduce((sum,row)=>sum+row.sent,0),remaining:products.reduce((sum,row)=>sum+row.remaining,0)},state=shipmentState(total);return `<article class="shipment-set-status"><header><span><b>${escapeHtml(name)}</b><small>${products.length} ürün</small></span><em class="shipment-state-badge ${state.key}"><i>${state.icon}</i>${state.label}</em></header><div class="shipment-set-totals"><span>Sipariş <b>${Math.floor(total.ordered)}</b></span><span>Sevk <b>${Math.floor(total.sent)}</b></span><span>Kalan <b>${Math.floor(total.remaining)}</b></span></div>${products.map(row=>{const productState=shipmentState(row);return `<div class="shipment-set-product"><span><b>${escapeHtml(row.partNo)}</b><small>${escapeHtml(row.description||'')}</small></span><span>${Math.floor(row.sent)} / ${Math.floor(row.ordered)}</span><i class="${productState.key}" title="${productState.label}">${productState.icon}</i></div>`}).join('')}</article>`}).join(''):'<div class="shipment-history-empty">Set veya ürün bilgisi bulunmuyor.</div>'}
function shipmentQuantityMarkup(item){const summary=shipmentSummary(item),available=summary.rows.filter(row=>row.remaining>0);return available.length?`<div class="shipment-quantity-head"><span>ÜRÜN / SET</span><span>SİPARİŞ</span><span>SEVK EDİLEN</span><span>KALAN</span><span>BU SEVKİYAT</span></div>${available.map(row=>{const ordered=Math.floor(row.ordered),sent=Math.floor(row.sent),remaining=Math.floor(row.remaining);return `<label class="shipment-quantity-row"><span><b>${escapeHtml(row.partNo)}</b><small>${escapeHtml(row.description||'')}</small><em>${escapeHtml(shipmentProductSet(item,row.partNo))}</em></span><strong>${ordered}</strong><strong>${sent}</strong><strong>${remaining}</strong><input name="shipmentQty" data-part-no="${escapeHtml(row.partNo)}" data-description="${escapeHtml(row.description||'')}" type="number" min="0" max="${remaining}" step="1" inputmode="numeric" value="0" aria-label="${escapeHtml(row.partNo)} sevk miktarı"></label>`}).join('')}`:'<div class="shipment-complete-message">Siparişteki tüm ürünler sevk edilmiş durumda.</div>'}
function shipmentHistoryMarkup(item){const history=shipmentHistory(item);return history.length?history.slice().reverse().map((entry,index)=>`<article><header><div><b>${history.length-index}. Sevkiyat</b><span>${escapeHtml(entry.shipmentDate||'Tarih yok')}</span></div><small>${escapeHtml(entry.createdBy||'Kullanıcı bilgisi yok')}</small></header><div>${(entry.items||[]).map(row=>`<p><span><b>${escapeHtml(row.partNo)}</b><small>${escapeHtml(row.description||'')}</small></span><strong>${escapeHtml(row.quantity)} adet</strong></p>`).join('')}</div>${entry.note?`<footer>${escapeHtml(entry.note)}</footer>`:''}</article>`).join(''):'<div class="shipment-history-empty">Henüz sevkiyat hareketi kaydedilmemiş.</div>'}
function shipmentDetailMarkup(item){const summary=shipmentSummary(item);return `<div class="detail-grid">${detailField('Durum',summary.label)}${detailField('Sipariş miktarı',`${summary.ordered} adet`)}${detailField('Sevk edilen',`${summary.sent} adet`)}${detailField('Kalan',`${summary.remaining} adet`)}</div><h4 class="shipment-detail-subheading">Ürün bazında sevkiyat</h4><div class="shipment-status-scroll detail-shipment-status">${shipmentStatusProductMarkup(item)}</div><h4 class="shipment-detail-subheading">Set bazında sevkiyat</h4><div class="shipment-status-scroll detail-shipment-sets">${shipmentStatusSetMarkup(item)}</div><h4 class="shipment-detail-subheading">Sevkiyat geçmişi</h4><div class="shipment-history-list detail-shipment-history">${shipmentHistoryMarkup(item)}</div>`}
